import React, { useState, useEffect } from 'react';
import { useOutletContext, Outlet, useLocation } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';
import '../../components/RealtimeWorkspace.css'; 

const ATSModule = () => {
  const context = useOutletContext();
  const location = useLocation();

  // Detect if we are on a sub-page (e.g., /ats/p1)
  const isSubPage = location.pathname.includes('/p');

  // Keep your existing state and upload logic
  const [loading, setLoading] = useState(false);
  const [localAnalysis, setLocalAnalysis] = useState(null);
  
  console.log("ATSModule - LocalAnalysis State:", localAnalysis);
  console.log("ATSModule - isSubPage:", isSubPage);
  // Ensure we pass the localAnalysis into the Outlet context
  const moduleContext = { 
    ...context, 
    ats: { data: localAnalysis, setter: setLocalAnalysis } 
  };

  const handleUpload = async (e) => {
  const file = e.target.files[0];
  if (!file) return;
  setLoading(true);
  const formData = new FormData();
  formData.append("file", file);
  try {
    const response = await fetch('http://localhost:8000/api/ats/optimize', {
      method: 'POST',
      body: formData,
    });
    const data = await response.json();
    
    // UPDATE LOCAL STATE
    setLocalAnalysis(data);
    
    // UPDATE GLOBAL STATE (The Bridge)
    // context.ats.setter comes from MainLayout
    if (context?.ats?.setter) {
       context.ats.setter(data);
    }
  } catch (error) {
    console.error("Upload failed:", error);
  } finally {
    setLoading(false);
  }
};

  return (
    <div className="workspace-container">
      <ProjectNavbar basePath="ats" links={["Async", "Skill", "Similarity", "DB"]} />
      
      {/* If a sub-page (P1-P4) is active, show it. Otherwise, show the Upload Dashboard */}
      {isSubPage ? (
       <Outlet context={moduleContext} />
      ) : (
        <div className="dashboard-content">
          <header className="workspace-header">
            <h2>ATS Optimization Engine</h2>
          </header>
          <div className="input-section">
            <label className="workspace-button">
              {loading ? 'Analyzing...' : 'Upload Resume'}
              <input type="file" onChange={handleUpload} style={{ display: 'none' }} />
            </label>
          </div>
          {localAnalysis && <pre>{JSON.stringify(localAnalysis, null, 2)}</pre>}
        </div>
      )}
    </div>
  );
};

export default ATSModule;
